/**
 *
 * Reldens - Test Maps Elements Editor
 *
 * Tests the map elements editor on a sample map generated by the maps wizard (MapsWizardBaseTest) and published in the
 * theme and dist maps folders like an imported room: the first element of the generated elements record moved one
 * column to the right and saved from a room view rewrites the live map with the element layer on its new tiles,
 * publishes the merged map with the moved element to the theme and dist maps, stores the moved record as the live
 * elements and writes one backup pair (map and elements) with the answered timestamp, while the same save from the
 * maps wizard leaves the published maps as they were; and a resize from a room view that removes two columns and two
 * rows around the center shrinks the live and the published maps and every layer, moves the elements one tile up and
 * left and writes a backup pair, while a resize that removes every column answers invalid dimensions and changes
 * nothing.
 *
 */

const { MapsWizardBaseTest } = require('./fixtures/maps-wizard-base-test');
const { JsonResponseRecorder } = require('./fixtures/json-response-recorder');
const { MapsElementsEditorSubscriber } = require('../lib/admin/server/subscribers/maps-elements-editor-subscriber');
const { FileHandler } = require('@reldens/server-utils');
const { sc } = require('@reldens/utils');

class TestMapsElementsEditor extends MapsWizardBaseTest
{

    constructor(config)
    {
        super(config, 'maps-elements-editor');
        this.mapName = 'map-named-001';
    }

    async prepareRoomMap()
    {
        await this.generateSampleMaps('multiple-by-loader', 'map-composite-data-with-names.json');
        let roomMap = {
            livePath: FileHandler.joinPaths(this.themeManager.projectGeneratedDataPath, this.mapName+'.json'),
            elementsPath: FileHandler.joinPaths(
                this.themeManager.projectGeneratedDataPath,
                this.mapName+'-room-map-elements.json'
            ),
            subscriber: new MapsElementsEditorSubscriber(
                this.createAdminManager([]),
                {get: (path, defaultValue) => defaultValue, getWithoutLogs: (path, defaultValue) => defaultValue},
                this.themeManager
            ),
            recorded: []
        };
        for(let mapsFolder of this.runtimeMapsFolders){
            FileHandler.copyFile(roomMap.livePath, FileHandler.joinPaths(mapsFolder, this.mapName+'.json'));
        }
        roomMap.originalMap = FileHandler.fetchFileJson(roomMap.livePath);
        roomMap.record = FileHandler.fetchFileJson(roomMap.elementsPath);
        roomMap.response = new JsonResponseRecorder().create(roomMap.recorded);
        return roomMap;
    }

    fetchPublishedMaps()
    {
        return this.runtimeMapsFolders.map(
            mapsFolder => FileHandler.fetchFileJson(FileHandler.joinPaths(mapsFolder, this.mapName+'.json'))
        );
    }

    async saveMovedElement(context)
    {
        let save = await this.prepareRoomMap();
        save.movedRecord = sc.deepJsonClone(save.record);
        let element = save.movedRecord.elements[0];
        element.bounds.col++;
        element.layers = element.layers.map(layer => Object.assign({}, layer, {
            tiles: layer.tiles.map(tile => Object.assign({}, tile, {col: tile.col + 1}))
        }));
        await save.subscriber.handleSaveMapEdit(
            {body: {mapElements: save.movedRecord, context}},
            save.response,
            {mapName: this.mapName}
        );
        save.liveMap = FileHandler.fetchFileJson(save.livePath);
        save.movedLayer = save.record.elements[0].layers[0];
        save.gid = save.movedLayer.tiles[0].gid;
        save.oldIndex = save.movedLayer.tiles[0].row * save.liveMap.width + save.movedLayer.tiles[0].col;
        save.elementTiles = [save.liveMap, ...this.fetchPublishedMaps()].map(mapJson => [save.oldIndex, save.oldIndex + 1].map(
            index => mapJson.layers.some(layer => sc.isArray(layer.data) && save.gid === layer.data[index])
        ));
        return save;
    }

    async testARoomSavePublishesTheMovedElementAndWritesABackup()
    {
        await this.test('an element moved and saved from a room view is published and backed up', async () => {
            let save = await this.saveMovedElement('room');
            let liveLayer = sc.fetchByProperty(save.liveMap.layers, 'name', save.movedLayer.name);
            let timestamp = save.recorded[0].timestamp;
            let backups = save.subscriber.backupArchive.listBackups(this.mapName);
            this.assert.deepStrictEqual(save.recorded, [{
                success: true,
                backupFiles: [
                    save.subscriber.backupArchive.path('mapBackup', this.mapName, timestamp),
                    save.subscriber.backupArchive.path('elementsBackup', this.mapName, timestamp)
                ],
                timestamp
            }]);
            this.assert.deepStrictEqual(
                [liveLayer.data[save.oldIndex], liveLayer.data[save.oldIndex + 1]],
                [0, save.gid],
                'The live element layer moved one tile to the right'
            );
            this.assert.deepStrictEqual(
                save.elementTiles,
                [[false, true], [false, true], [false, true]],
                'The live, theme and dist maps show the moved element'
            );
            this.assert.deepStrictEqual(
                [
                    FileHandler.fetchFileJson(save.elementsPath),
                    backups.map(backup => backup.timestamp),
                    FileHandler.fetchFileJson(backups[0].mapJsonPath),
                    FileHandler.fetchFileJson(backups[0].elementsFilePath)
                ],
                [save.movedRecord, [timestamp], save.liveMap, save.movedRecord]
            );
            FileHandler.remove(this.testFolder);
        });
    }

    async testAWizardSaveKeepsThePublishedMaps()
    {
        await this.test('an element moved and saved from the maps wizard is not published', async () => {
            let save = await this.saveMovedElement('wizard');
            this.assert.deepStrictEqual(
                save.elementTiles,
                [[false, true], [true, false], [true, false]],
                'Only the live map moved, the theme and dist maps keep the element on its old tiles'
            );
            FileHandler.remove(this.testFolder);
        });
    }

    async testARoomResizeShrinksThePublishedMapAndMovesTheElements()
    {
        await this.test('a resize from a room view shrinks the live and published maps and an invalid one changes nothing', async () => {
            let resize = await this.prepareRoomMap();
            let publish = resize.subscriber.publishIfRoomContext.bind(resize.subscriber);
            let width = resize.originalMap.width - 2;
            let height = resize.originalMap.height - 2;
            resize.subscriber.mapResizePersister.handle(
                {body: {context: 'room', anchor: 'center', removeHorizontal: 2, removeVertical: 2}},
                resize.response,
                {mapName: this.mapName},
                publish
            );
            let resizedMap = FileHandler.fetchFileJson(resize.livePath);
            let resizedRecord = FileHandler.fetchFileJson(resize.elementsPath);
            let publishedSizes = this.fetchPublishedMaps().map(mapJson => [mapJson.width, mapJson.height]);
            let backupsCount = resize.subscriber.backupArchive.listBackups(this.mapName).length;
            resize.subscriber.mapResizePersister.handle(
                {body: {context: 'room', anchor: 'center', removeHorizontal: width, removeVertical: 0}},
                resize.response,
                {mapName: this.mapName},
                publish
            );
            let originalBounds = resize.record.elements[0].bounds;
            this.assert.deepStrictEqual(resize.recorded, [
                {success: true, width, height},
                {success: false, offending: [], error: 'invalidDimensions'}
            ]);
            this.assert.deepStrictEqual(
                [
                    [resizedMap.width, resizedMap.height],
                    resizedMap.layers.every(layer => !sc.isArray(layer.data) || width * height === layer.data.length),
                    publishedSizes,
                    resizedRecord.elements[0].bounds,
                    backupsCount,
                    FileHandler.fetchFileJson(resize.livePath).width
                ],
                [
                    [width, height],
                    true,
                    [[width, height], [width, height]],
                    Object.assign({}, originalBounds, {col: originalBounds.col - 1, row: originalBounds.row - 1}),
                    1,
                    width
                ]
            );
            FileHandler.remove(this.testFolder);
        });
    }

}

module.exports.TestMapsElementsEditor = TestMapsElementsEditor;
